-- 7회차 5: 팩터 z 분산 진단 (docs/factors.md 12.9). 국내 최신 팩터의 결측 지표 수별 z 분산·만점/0점 비율. db-status.yml 의 sql 입력으로 한 번 돌린다(주석 줄은 빼고)
WITH d AS (SELECT MAX(fx.as_of_date) AS d FROM factors fx JOIN stocks s ON s.id = fx.stock_id WHERE s.country = 'KR'), v AS (SELECT MAX(fc.calc_version) AS v FROM factors fc WHERE fc.as_of_date = (SELECT d FROM d)), x AS (SELECT f.factor, COALESCE(json_array_length(f.missing_fields), 0) AS k_missing, f.zscore AS z, f.score FROM factors f JOIN stocks s ON s.id = f.stock_id WHERE s.country = 'KR' AND f.as_of_date = (SELECT d FROM d) AND f.calc_version = (SELECT v FROM v) AND f.zscore IS NOT NULL) SELECT (SELECT d FROM d) AS as_of, factor, k_missing, COUNT(*) AS n, ROUND(AVG(z * z) - AVG(z) * AVG(z), 3) AS var_z, ROUND(SUM(score >= 99.95) * 1.0 / COUNT(*), 4) AS share_100, ROUND(SUM(score <= 0.05) * 1.0 / COUNT(*), 4) AS share_0 FROM x GROUP BY factor, k_missing ORDER BY factor, k_missing LIMIT 60
